package org.jlinalg.cli;

import static org.jlinalg.cli.StudyPublicEvidence.*;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.jlinalg.study.StudyColocalizationPolicy;
import org.jlinalg.study.StudyNeed;
import org.jlinalg.study.StudyOperationExecutor.Context;

/** Complete signal-pair reporting; posterior probabilities never become association FDR. */
final class StudyColocalizationReview {
    private StudyColocalizationReview() { }
    static final String CAVEAT="Colocalization posteriors condition on the observed variants, allele alignment, LD, fine-mapping model and priors. A complete_region declaration is not independent verification of dense unselected coverage. Colocalization does not establish causal direction or biological function. Missing/uncertain coverage, weak signals, convergence and prior sensitivity must accompany interpretation; absent or unestimable evidence is not evidence against sharing.";
    static final String PARTIAL="Exploratory partial-data colocalization posteriors are conditional on observed, selected variants. Missing variants, significance filtering, unequal coverage, winner's curse and unknown overlap can materially bias them. These are not conventional complete-region results; a null result is not evidence against a shared causal variant.";
    static final List<String> COLUMNS=List.of("feature_id","region_id","pair_id","signal_pair","trait1_effect_index","trait2_effect_index","variants","trait1_lead_variant","trait2_lead_variant","pp_h0","pp_h1","pp_h2","pp_h3","pp_h4","pp_h4_given_h3_h4","trait1_prior","trait2_prior","shared_prior","sensitivity_priors","pp_h4_min","pp_h4_max","posterior_threshold","prior_stability","exposure_converged","outcome_converged","convergence_fallback_used","exposure_observed_variants","outcome_observed_variants","aligned_variants","exposure_variant_match_fraction","outcome_variant_match_fraction","outcome_candidate_match_fraction","exposure_lead_aligned","outcome_lead_aligned","exposure_export_p_threshold","outcome_export_p_threshold","exposure_selection_basis","outcome_selection_basis","exposure_complete_region_declared","outcome_complete_region_declared","exposure_sample_size","outcome_sample_size","sample_overlap","exposure_trait","outcome_trait","exposure_assay","exposure_tissue","exposure_source_id","outcome_source_id","exposure_citation","outcome_citation","genome_build","ancestry","region_chromosome","region_start","region_end","aligned_largest_gap_bp","aligned_left_edge_bp","aligned_right_edge_bp","evidence_grade","status","required_manuscript_caveat");
    static Map<String,Object> policy(Context c){return StudyColocalizationPolicy.resolve(map(StudyResultTables.analysis(c).get("colocalization")));}

    static void analyze(Context c,Map<String,Object> pair,Path directory,Map<String,Object> record)throws IOException {
        var p=policy(c);var priors=new ArrayList<Double>();priors.add(((Number)p.get("shared_prior")).doubleValue());for(Object value:list(p.get("shared_prior_sensitivity")))priors.add(((Number)value).doubleValue());
        var primary=new LinkedHashMap<String,Map<String,String>>();var gridRows=new ArrayList<String[]>();var values=new LinkedHashMap<String,List<Double>>();var commands=new ArrayList<Object>();
        for(int i=0;i<priors.size();i++){
            String name=i==0?"colocalization.tsv":i==1?"colocalization-prior-sensitivity.tsv":"colocalization-prior-sensitivity-"+i+".tsv";
            var args=new ArrayList<>(List.of("--trait1",directory.resolve("exposure.effects.tsv").toString(),"--trait2",directory.resolve("outcome.effects.tsv").toString(),"--trait1-prior",p.get("trait1_prior").toString(),"--trait2-prior",p.get("trait2_prior").toString(),"--shared-prior",priors.get(i).toString(),"--minimum-overlap",p.get("minimum_component_overlap").toString(),"--out",directory.resolve(name).toString()));
            StudyGeneticEvidence.run("coloc",args,directory.resolve(i==0?"coloc-command.log":i==1?"coloc-sensitivity-command.log":"coloc-sensitivity-"+i+"-command.log"));
            var table=DelimitedData.readResult(directory.resolve(name));var observed=new java.util.LinkedHashSet<String>();
            for(String[] row:table.rows()){
                var fields=new LinkedHashMap<String,String>();for(int j=0;j<table.header().size();j++)fields.put(table.header().get(j),row[j]);String key=fields.get("trait1_effect_index")+":"+fields.get("trait2_effect_index");if(!observed.add(key))throw new IOException("Duplicate colocalization signal pair");
                if(i==0)primary.put(key,fields);else if(!primary.containsKey(key))throw new IOException("Prior sensitivity changed the retained signal-pair universe");
                double h4=number(fields.get("posterior_h4"));values.computeIfAbsent(key,k->new ArrayList<>()).add(h4);
                gridRows.add(new String[]{text(pair.get("feature_id")),text(pair.get("id")),fields.get("trait1_effect_index"),fields.get("trait2_effect_index"),i==0?"primary":"sensitivity",priors.get(i).toString(),fields.get("posterior_h0"),fields.get("posterior_h1"),fields.get("posterior_h2"),fields.get("posterior_h3"),fields.get("posterior_h4")});
            }
            if(i>0&&!observed.equals(primary.keySet()))throw new IOException("Prior sensitivity omitted primary signal pairs");
            commands.add(Map.of("shared_prior",priors.get(i),"role",i==0?"primary":"sensitivity","artifact",name,"sha256",FollowupSupport.hash(directory.resolve(name)),"command",args));
        }
        FollowupSupport.table(directory.resolve("colocalization-prior-grid.tsv"),List.of("feature_id","pair_id","trait1_effect_index","trait2_effect_index","role","shared_prior","pp_h0","pp_h1","pp_h2","pp_h3","pp_h4"),gridRows);
        var coverage=map(record.get("regional_coverage"));var effective=map(record.get("effective_parameters"));var fx=map(effective.get("exposure_fine_mapping"));var fy=map(effective.get("outcome_fine_mapping"));boolean fallback=Boolean.TRUE.equals(fx.get("fallback_used"))||Boolean.TRUE.equals(fy.get("fallback_used"));
        String caveat=text(record.get("required_manuscript_caveat"));if(fallback)caveat+=" The prespecified exploratory fallback reduced the maximum SuSiE effect count to obtain convergence; component-model sensitivity remains unresolved.";record.put("required_manuscript_caveat",caveat);
        var rows=new ArrayList<String[]>();for(var entry:primary.entrySet()){
            var fields=entry.getValue();var row=new LinkedHashMap<String,Object>();row.put("feature_id",pair.get("feature_id"));row.put("region_id",pair.get("id"));row.put("pair_id",pair.get("id"));for(String field:List.of("signal_pair","trait1_effect_index","trait2_effect_index","variants","trait1_lead_variant","trait2_lead_variant"))row.put(field,fields.get(field));
            double sum=0;for(int h=0;h<=4;h++){double v=number(fields.get("posterior_h"+h));if(v<0||v>1)throw new IOException("Invalid posterior probability");sum+=v;row.put("pp_h"+h,v);}if(Math.abs(sum-1)>1e-8)throw new IOException("Posterior hypotheses do not sum to one");
            double h3=number(fields.get("posterior_h3")),h4=number(fields.get("posterior_h4"));row.put("pp_h4_given_h3_h4",h3+h4>0?h4/(h3+h4):"NA");
            var observed=values.get(entry.getKey());double min=observed.stream().mapToDouble(Double::doubleValue).min().orElseThrow(),max=observed.stream().mapToDouble(Double::doubleValue).max().orElseThrow();
            row.put("trait1_prior",p.get("trait1_prior"));row.put("trait2_prior",p.get("trait2_prior"));row.put("shared_prior",p.get("shared_prior"));row.put("sensitivity_priors",String.join(";",priors.subList(1,priors.size()).stream().map(Object::toString).toList()));row.put("pp_h4_min",min);row.put("pp_h4_max",max);row.put("posterior_threshold",p.getOrDefault("posterior_threshold","not_registered"));
            row.put("prior_stability",p.get("posterior_threshold") instanceof Number threshold?min>=threshold.doubleValue()?"above_registered_threshold_all_priors":max<threshold.doubleValue()?"below_registered_threshold_all_priors":"crosses_registered_threshold":"not_classified_no_registered_threshold");
            row.put("exposure_converged",fx.getOrDefault("converged","not_recorded"));row.put("outcome_converged",fy.getOrDefault("converged","not_recorded"));row.put("convergence_fallback_used",fallback);row.put("exposure_observed_variants",map(coverage.get("exposure")).getOrDefault("observed_regional_variants","NA"));row.put("outcome_observed_variants",map(coverage.get("outcome")).getOrDefault("observed_regional_variants","NA"));
            row.put("aligned_variants",record.get("aligned_variants"));row.put("exposure_variant_match_fraction",coverage.getOrDefault("exposure_observed_match_fraction","NA"));row.put("outcome_variant_match_fraction",coverage.getOrDefault("outcome_observed_match_fraction","NA"));row.put("outcome_candidate_match_fraction",coverage.getOrDefault("outcome_candidate_match_fraction","NA"));row.put("exposure_lead_aligned",coverage.getOrDefault("exposure_lead_aligned","NA"));row.put("outcome_lead_aligned",coverage.getOrDefault("outcome_lead_aligned","NA"));for(String source:List.of("exposure","outcome")){var sourceCoverage=map(coverage.get(source));row.put(source+"_export_p_threshold",sourceCoverage.getOrDefault("export_p_threshold","not_declared"));row.put(source+"_selection_basis",sourceCoverage.getOrDefault("selection_basis","not_declared"));row.put(source+"_complete_region_declared",sourceCoverage.getOrDefault("complete_region_declared","not_declared"));row.put(source+"_sample_size",map(effective.get(source+"_fine_mapping")).getOrDefault("sample_size","not_declared"));}
            for(String source:List.of("exposure","outcome")){var declaration=map(pair.get(source));for(String field:List.of("trait","source_id","citation"))row.put(source+"_"+field,declaration.getOrDefault(field,"not_declared"));}var exposure=map(pair.get("exposure"));row.put("exposure_assay",exposure.getOrDefault("assay","not_declared"));row.put("exposure_tissue",exposure.getOrDefault("tissue","not_declared"));row.put("genome_build",exposure.getOrDefault("genome_build","not_declared"));row.put("ancestry",exposure.getOrDefault("ancestry","not_declared"));
            var region=map(pair.get("region"));row.put("region_chromosome",region.getOrDefault("chromosome","not_declared"));row.put("region_start",region.getOrDefault("start","not_declared"));row.put("region_end",region.getOrDefault("end","not_declared"));row.put("sample_overlap",pair.getOrDefault("sample_overlap","not_declared"));var gaps=map(coverage.get("aligned_position_gaps"));row.put("aligned_largest_gap_bp",gaps.getOrDefault("largest_between_observed_positions_bp","NA"));row.put("aligned_left_edge_bp",gaps.getOrDefault("left_edge_bp","NA"));row.put("aligned_right_edge_bp",gaps.getOrDefault("right_edge_bp","NA"));
            row.put("evidence_grade",record.get("evidence_grade"));row.put("status","complete");row.put("required_manuscript_caveat",caveat);
            rows.add(COLUMNS.stream().map(key->text(row.getOrDefault(key,"NA"))).toArray(String[]::new));
        }
        FollowupSupport.table(directory.resolve("colocalization-results.tsv"),COLUMNS,rows);
        record.put("colocalization",StudyGeneticEvidence.preview(directory.resolve("colocalization.tsv")));record.put("prior_sensitivity",StudyGeneticEvidence.preview(directory.resolve("colocalization-prior-sensitivity.tsv")));record.put("signal_pairs",rows.size());record.put("full_signal_results",Map.of("artifact",directory.getFileName()+"/colocalization-results.tsv","sha256",FollowupSupport.hash(directory.resolve("colocalization-results.tsv")),"rows",rows.size(),"preview_only",false));
        var parameters=new LinkedHashMap<>(effective);parameters.put("colocalization",Map.of("registered_policy",p,"signal_model","SuSiE single-effect components","posterior_decision_threshold",p.getOrDefault("posterior_threshold","Not applied; posterior probabilities are reported"),"partial_region_exploratory",Boolean.TRUE.equals(pair.get("partial_colocalization")),"prior_runs",commands));record.put("effective_parameters",parameters);
    }

    static List<String> finish(Context c,List<Object> pairs,Map<String,StudyBioinformatics.Feature> eligible,Map<String,Object> details,List<StudyNeed> needs)throws IOException {
        var rows=new ArrayList<String[]>();var dispositions=new ArrayList<String[]>();var requested=new java.util.HashSet<String>();
        for(Object raw:pairs){var pair=map(raw);String id=text(pair.get("pair_id")),feature=text(pair.get("feature_id"));requested.add(feature);Path table=c.outputDirectory().resolve(id).resolve("colocalization-results.tsv");
            if(Files.isRegularFile(table)){var data=DelimitedData.readResult(table);if(!data.header().equals(COLUMNS))throw new IOException("Unexpected canonical colocalization columns");rows.addAll(data.rows());}
            dispositions.add(new String[]{feature,id,text(pair.get("status")),text(pair.get("reason")),text(pair.get("evidence_grade")),text(pair.get("required_manuscript_caveat"))});
        }
        for(String feature:eligible.keySet())if(!requested.contains(feature))dispositions.add(new String[]{feature,"","not_requested_no_reviewed_pair","No approved source pair was supplied for this eligible feature; absence is not a null colocalization result","source_unavailable",CAVEAT});
        if(pairs.isEmpty()&&!eligible.isEmpty())needs.add(StudyNeed.review("colocalization-pairs:"+c.operation().get("hypothesis"),"Supply reviewed colocalization sources","No reviewed source pair was available for the eligible mapped findings",true));
        FollowupSupport.table(c.outputDirectory().resolve("colocalization-results.tsv"),COLUMNS,rows);FollowupSupport.table(c.outputDirectory().resolve("colocalization-feature-dispositions.tsv"),List.of("feature_id","pair_id","status","reason","evidence_grade","required_manuscript_caveat"),dispositions);
        var summary=new LinkedHashMap<String,Object>();summary.put("signal_pairs",rows.size());summary.put("eligible_mapped_features",eligible.size());summary.put("feature_selection_scope",policy(c).containsKey("max_features")?"explicitly_capped_primary_significant_features":"all_primary_significant_mapped_features");summary.put("contextual_top_ten_cap_applies",false);summary.put("requested_features",requested.size());summary.put("unrequested_features",eligible.keySet().stream().filter(f->!requested.contains(f)).count());summary.put("registered_policy",policy(c));summary.put("canonical_results","colocalization-results.tsv");summary.put("canonical_sha256",FollowupSupport.hash(c.outputDirectory().resolve("colocalization-results.tsv")));summary.put("required_manuscript_caveat",CAVEAT);summary.put("interpretation","Every computed signal pair is retained without a preview cap. Missing pairs and non-estimable models remain explicit; posterior thresholds are not FDR and never replace primary association eligibility.");details.put("colocalization_review",summary);StudyPublicEvidence.write(c.outputDirectory().resolve("colocalization-review.yaml"),summary);
        return List.of("colocalization-results.tsv","colocalization-feature-dispositions.tsv","colocalization-review.yaml");
    }
    private static double number(String raw)throws IOException{try{double v=Double.parseDouble(raw);if(!Double.isFinite(v))throw new NumberFormatException();return v;}catch(NumberFormatException bad){throw new IOException("Invalid finite posterior",bad);}}
}
